<?php
require __DIR__.'/config.php';
if(empty($_SESSION['admin'])){header('Location: admin-login.php');exit;}
$db=getDb();$errors=[];$notice=(string)($_GET['notice']??'');
function challengeEscape($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function challengeDateInput(?string $value):string{if(!$value)return '';try{return (new DateTimeImmutable($value,new DateTimeZone('America/Denver')))->setTimezone(new DateTimeZone('America/Denver'))->format('Y-m-d\\TH:i');}catch(Throwable $e){return '';}}
function challengeParseLocalInput(string $value):?DateTimeImmutable{if($value==='')return null;$date=DateTimeImmutable::createFromFormat('!Y-m-d\\TH:i',$value,new DateTimeZone('America/Denver'));$errors=DateTimeImmutable::getLastErrors();if(!$date||($errors&&($errors['warning_count']||$errors['error_count']))||$date->format('Y-m-d\\TH:i')!==$value)throw new RuntimeException('Enter a valid Mountain Time date and time.');return $date;}
function challengeFind(PDO $db,int $id):?array{$s=$db->prepare('SELECT * FROM challenges WHERE id=?');$s->execute([$id]);return $s->fetch(PDO::FETCH_ASSOC)?:null;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);
 try{
  if($action==='save_challenge'){
   $title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));$instructions=trim((string)($_POST['instructions']??''));$status=(string)($_POST['status']??'draft');
   if($title===''||strlen($title)>160||$description===''||strlen($description)>5000||strlen($instructions)>5000||!in_array($status,['draft','published','closed'],true))throw new RuntimeException('Enter a valid title, description, instructions, and status.');
   $now=date('c');$start=trim((string)($_POST['starts_at']??''));$end=trim((string)($_POST['ends_at']??''));
   $startDate=challengeParseLocalInput($start);$endDate=challengeParseLocalInput($end);
   if($startDate&&$endDate&&$endDate<$startDate)throw new RuntimeException('End date and time must be after the start date and time.');
   $start=$startDate?$startDate->format('Y-m-d H:i:s'):'';$end=$endDate?$endDate->format('Y-m-d H:i:s'):'';
   if($id){if(!challengeFind($db,$id))throw new RuntimeException('Challenge not found.');$s=$db->prepare('UPDATE challenges SET title=?,description=?,instructions=?,starts_at=?,ends_at=?,status=?,updated_at=? WHERE id=?');$s->execute([$title,$description,$instructions,$start?:null,$end?:null,$status,$now,$id]);}
   else{$s=$db->prepare('INSERT INTO challenges(title,description,instructions,starts_at,ends_at,status,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$title,$description,$instructions,$start?:null,$end?:null,$status,(string)($_SESSION['username']??'admin'),$now,$now]);}
   header('Location: admin-challenges.php?notice=saved');exit;
  }
  if($action==='delete_challenge'){if(!$id||!challengeFind($db,$id))throw new RuntimeException('Challenge not found.');$s=$db->prepare('DELETE FROM challenges WHERE id=?');$s->execute([$id]);header('Location: admin-challenges.php?notice=deleted');exit;}
  if($action==='save_submission'){
   $challengeId=(int)($_POST['challenge_id']??0);$challenge=challengeFind($db,$challengeId);if(!$challenge)throw new RuntimeException('Choose a valid challenge.');
   $title=trim((string)($_POST['submission_title']??''));$description=trim((string)($_POST['submission_description']??''));$label=trim((string)($_POST['submitter_label']??''));$url=trim((string)($_POST['source_url']??''));$sq=(int)($_POST['squadron_id']??0);$status=(string)($_POST['submission_status']??'published');
   if($title===''||strlen($title)>160||$description===''||strlen($description)>5000||!in_array($status,['draft','published'],true))throw new RuntimeException('Enter a valid submission title, description, and status.');
   if($url!==''&&(!filter_var($url,FILTER_VALIDATE_URL)||strtolower((string)parse_url($url,PHP_URL_SCHEME))!=='https'))throw new RuntimeException('Source link must be a valid HTTPS URL.');
   if($sq&&!$db->query('SELECT 1 FROM squadrons WHERE id='.(int)$sq)->fetchColumn())throw new RuntimeException('Invalid squadron.');
   $now=date('c');$s=$db->prepare('INSERT INTO challenge_submissions(challenge_id,title,description,squadron_id,submitter_label,source_url,status,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->execute([$challengeId,$title,$description,$sq?:null,$label?:null,$url?:null,$status,(string)($_SESSION['username']??'admin'),$now,$now]);header('Location: admin-challenges.php?challenge='.$challengeId.'&notice=submission');exit;
  }
  if($action==='delete_submission'){$s=$db->prepare('DELETE FROM challenge_submissions WHERE id=?');$s->execute([$id]);header('Location: admin-challenges.php?notice=deleted');exit;}
  if($action==='submission_status'){$status=(string)($_POST['status']??'');if(!in_array($status,['draft','published'],true))throw new RuntimeException('Invalid submission status.');$s=$db->prepare('UPDATE challenge_submissions SET status=?,updated_at=? WHERE id=?');$s->execute([$status,date('c'),$id]);header('Location: admin-challenges.php?notice=status');exit;}
  throw new RuntimeException('Unknown action.');
 }catch(Throwable $e){$errors[]=$e->getMessage();}
}
$edit=challengeFind($db,(int)($_GET['edit']??0));$selected=(int)($_GET['challenge']??0);$challenges=$db->query("SELECT c.*,(SELECT COUNT(*) FROM challenge_submissions s WHERE s.challenge_id=c.id) submission_count,(SELECT COUNT(*) FROM engagement_awards a WHERE a.challenge_id=c.id) award_count FROM challenges c ORDER BY c.created_at DESC")->fetchAll(PDO::FETCH_ASSOC);
$squadrons=$db->query('SELECT id,name FROM squadrons ORDER BY id')->fetchAll(PDO::FETCH_ASSOC);$submissions=[];if($selected){$s=$db->prepare("SELECT s.*,q.name squadron_name FROM challenge_submissions s LEFT JOIN squadrons q ON q.id=s.squadron_id WHERE s.challenge_id=? ORDER BY s.created_at DESC");$s->execute([$selected]);$submissions=$s->fetchAll(PDO::FETCH_ASSOC);}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage Challenges | GroupStatistics</title><link rel="stylesheet" href="site-ui.css"><link rel="stylesheet" href="site-components.css"><style>body{margin:0;background:#f3f6fa;color:#1e293b;font:16px/1.5 Arial}.top{background:#002147;color:white;padding:20px}.topin,main{max-width:1200px;margin:auto}.top a{color:white;margin-right:12px}main{padding:22px 14px}.grid{display:grid;grid-template-columns:minmax(300px,.9fr) minmax(0,1.1fr);gap:18px}.panel{background:white;border:1px solid #dbe3ed;border-radius:12px;padding:18px;min-width:0}.panel h2{color:#002147;margin-top:0}label{display:block;font-weight:bold;margin:12px 0 5px}input,textarea,select{box-sizing:border-box;width:100%;padding:10px;border:1px solid #cbd5e1;border-radius:7px;font:inherit}textarea{min-height:90px}.btn{display:inline-block;border:0;border-radius:7px;padding:9px 12px;background:#002147;color:white;text-decoration:none;font-weight:bold;cursor:pointer}.secondary{background:#e8eef6;color:#002147}.danger{background:#fff0f0;color:#a21d2a}.row{border-top:1px solid #dbe3ed;padding:14px 0}.meta,.hint{color:#64748b;font-size:.86rem}.actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.alert{padding:12px;background:#eaf8ef;margin-bottom:14px}.error{background:#fff0f0;color:#8d1825}.inline{display:inline}.admin-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 16px}.admin-tabs button{border:1px solid #cbd5e1;border-radius:8px;padding:10px 16px;background:#e8eef6;color:#002147;font-weight:700;cursor:pointer}.admin-tabs button.active{background:#002147;color:white}#awards-panel iframe{display:block;width:100%;height:1900px;border:0;background:white;border-radius:10px}@media(max-width:850px){.grid{grid-template-columns:1fr}}</style></head><body>
<?php require_once __DIR__.'/site-header.php';renderGroupSiteHeader(false);?><header class="top"><div class="topin"><h1>🎯 Manage Challenges</h1><a href="challenges.php">Public challenge board ↗</a><a href="admin-panel.php">Admin panel</a></div></header><main>
<?php if($notice):?><p class="alert"><?php echo challengeEscape($notice==='submission'?'Submission posted.':($notice==='deleted'?'Record deleted.':'Changes saved.'));?></p><?php endif;?><?php foreach($errors as $e):?><p class="alert error"><?php echo challengeEscape($e);?></p><?php endforeach;?>
<nav class="admin-tabs" aria-label="Challenge administration"><button type="button" class="active" data-admin-tab="challenges">Challenges &amp; Submissions</button><button type="button" data-admin-tab="awards">Awards</button></nav><section id="challenges-panel"><div class="grid"><section class="panel"><h2><?php echo $edit?'Edit challenge':'Post a challenge';?></h2><p class="hint">Publish the challenge first. Later, return here to post submissions recorded outside this website. Awards can be attached separately in Manage Challenge Awards.</p><form method="post"><input type="hidden" name="action" value="save_challenge"><input type="hidden" name="id" value="<?php echo (int)($edit['id']??0);?>"><label>Challenge title</label><input name="title" maxlength="160" required value="<?php echo challengeEscape($edit['title']??'');?>"><label>Description</label><textarea name="description" maxlength="5000" required><?php echo challengeEscape($edit['description']??'');?></textarea><label>Instructions / criteria</label><textarea name="instructions" maxlength="5000"><?php echo challengeEscape($edit['instructions']??'');?></textarea><label>Start date (optional)</label><input type="datetime-local" name="starts_at" value="<?php echo !empty($edit['starts_at'])?date('Y-m-d\TH:i',strtotime($edit['starts_at'])):'';?>"><label>End date (optional)</label><input type="datetime-local" name="ends_at" value="<?php echo !empty($edit['ends_at'])?date('Y-m-d\TH:i',strtotime($edit['ends_at'])):'';?>"><label>Status</label><select name="status"><option value="draft" <?php echo ($edit['status']??'draft')==='draft'?'selected':'';?>>Draft</option><option value="published" <?php echo ($edit['status']??'')==='published'?'selected':'';?>>Published</option><option value="closed" <?php echo ($edit['status']??'')==='closed'?'selected':'';?>>Closed</option></select><div class="actions"><button class="btn">Save challenge</button><a class="btn secondary" href="admin-challenges.php">New / cancel</a></div></form>
<hr><h2>Post a submission</h2><p class="hint">This is an admin-posted record of a submission received elsewhere; cadets do not submit through this form.</p><form method="post"><input type="hidden" name="action" value="save_submission"><label>Challenge</label><select name="challenge_id" required><option value="">Choose challenge</option><?php foreach($challenges as $c):?><option value="<?php echo (int)$c['id'];?>" <?php echo $selected===(int)$c['id']?'selected':'';?>><?php echo challengeEscape($c['title']);?></option><?php endforeach;?></select><label>Submission title / team</label><input name="submission_title" maxlength="160" required><label>Submission summary</label><textarea name="submission_description" maxlength="5000" required></textarea><label>Squadron (optional)</label><select name="squadron_id"><option value="0">Not specified</option><?php foreach($squadrons as $sq):?><option value="<?php echo (int)$sq['id'];?>"><?php echo challengeEscape($sq['name']);?></option><?php endforeach;?></select><label>Submitter / team label (optional)</label><input name="submitter_label" maxlength="160"><label>External source link (optional)</label><input type="url" name="source_url" placeholder="https://..."><label>Visibility</label><select name="submission_status"><option value="published">Publish immediately</option><option value="draft">Keep as draft</option></select><button class="btn" style="margin-top:14px">Post submission</button></form></section>
<section class="panel"><h2>Challenges</h2><?php foreach($challenges as $c):?><article class="row"><strong><?php echo challengeEscape($c['title']);?></strong> · <b><?php echo challengeEscape($c['status']);?></b><p class="meta"><?php echo (int)$c['submission_count'];?> submissions · <?php echo (int)$c['award_count'];?> awards</p><p><?php echo nl2br(challengeEscape($c['description']));?></p><div class="actions"><a class="btn secondary" href="admin-challenges.php?edit=<?php echo (int)$c['id'];?>">Edit</a><a class="btn secondary" href="admin-challenges.php?challenge=<?php echo (int)$c['id'];?>">Manage submissions</a><button class="btn secondary" type="button" onclick="showAwards(<?php echo (int)$c['id'];?>)">Post an award</button><form method="post" class="inline" onsubmit="return confirm('Delete this challenge and its submissions? Linked awards will remain but become unlinked.');"><input type="hidden" name="action" value="delete_challenge"><input type="hidden" name="id" value="<?php echo (int)$c['id'];?>"><button class="btn danger">Delete</button></form></div></article><?php endforeach;?><?php if(!$challenges):?><p class="hint">No challenges posted yet.</p><?php endif;?>
<?php if($selected):?><hr><h2>Submissions</h2><?php foreach($submissions as $s):?><article class="row"><strong><?php echo challengeEscape($s['title']);?></strong> · <?php echo challengeEscape($s['status']);?><p><?php echo nl2br(challengeEscape($s['description']));?></p><p class="meta"><?php echo challengeEscape($s['squadron_name']?:'Squadron not specified');?><?php if($s['submitter_label']):?> · <?php echo challengeEscape($s['submitter_label']);?><?php endif;?></p><?php if($s['source_url']):?><a href="<?php echo challengeEscape($s['source_url']);?>" target="_blank" rel="noopener">External source ↗</a><?php endif;?><div class="actions"><form method="post"><input type="hidden" name="action" value="submission_status"><input type="hidden" name="id" value="<?php echo (int)$s['id'];?>"><input type="hidden" name="status" value="<?php echo $s['status']==='published'?'draft':'published';?>"><button class="btn secondary"><?php echo $s['status']==='published'?'Unpublish':'Publish';?></button></form><form method="post" onsubmit="return confirm('Delete this submission?');"><input type="hidden" name="action" value="delete_submission"><input type="hidden" name="id" value="<?php echo (int)$s['id'];?>"><button class="btn danger">Delete</button></form></div></article><?php endforeach;?><?php endif;?></section></div></section><section id="awards-panel" hidden><iframe id="awards-frame" src="about:blank" title="Manage challenge and group awards" loading="lazy"></iframe></section></main><script>function selectAdminTab(show){document.getElementById("challenges-panel").hidden=show!=="challenges";document.getElementById("awards-panel").hidden=show!=="awards";document.querySelectorAll("[data-admin-tab]").forEach(tab=>tab.classList.toggle("active",tab.dataset.adminTab===show));}function showAwards(challengeId){document.getElementById("awards-frame").src="admin-awards.php?embed=1"+(challengeId?"&challenge="+encodeURIComponent(challengeId):"");selectAdminTab("awards");}document.querySelectorAll("[data-admin-tab]").forEach(button=>button.addEventListener("click",()=>{if(button.dataset.adminTab==="awards"&&!document.getElementById("awards-frame").src.endsWith("admin-awards.php?embed=1")){document.getElementById("awards-frame").src="admin-awards.php?embed=1";}selectAdminTab(button.dataset.adminTab);}));</script></body></html>
